	ll ans = 0;
	for(int s = 0; s <= N / 4; ++s){ // computing the answer for N using the precomputed P(x) polynomial
		ans = (ans + fact[N - 2 * s] * ifact[s] % mod * P[N - 4 * s]) % mod;
	}

	cout << ans << '\n';
}

